# Import
created = 0
skipped = 0
for item in WORDS:
    text, phonetic, pos, def_en, def_vi, ex_en, ex_vi, level = item
    obj, is_new = Word.objects.get_or_create(
        text=text,
        defaults=dict(
            phonetic=phonetic,
            part_of_speech=pos,
            definition_en=def_en,
            definition_vi=def_vi,
            example_en=ex_en,
            example_vi=ex_vi,
            level=level,
        ),
    )
    if is_new:
        created += 1
    else:
        skipped += 1

print(f"Hoàn thành: {created} từ mới, {skipped} bỏ qua (đã tồn tại).")
print(f"Tổng từ vựng hiện tại: {Word.objects.count()}")
